// 8-bit sound effects (generated by scripts/gen-sounds.mjs). Silent when muted in Profile
// or when the dev client has no expo-audio yet.
import { audioModule } from '../lib/nativeOptional';
import { soundMuted } from '../lib/prefs';

export type SoundName = 'bet' | 'tick' | 'win' | 'loss';

const SOURCES: Record<SoundName, number> = {
  bet: require('../../assets/sounds/bet.wav'),
  tick: require('../../assets/sounds/tick.wav'),
  win: require('../../assets/sounds/win.wav'),
  loss: require('../../assets/sounds/loss.wav'),
};

type Player = { play(): void; pause(): void; seekTo(seconds: number): Promise<void>; volume: number };
const players = new Map<SoundName, Player>();
let modeSet = false;

function player(name: SoundName): Player | null {
  const audio = audioModule();
  if (!audio) return null;
  let p = players.get(name);
  if (!p) {
    try {
      if (!modeSet) {
        modeSet = true;
        // Effects mix with whatever else is playing and never take the audio focus.
        void audio.setAudioModeAsync({ interruptionMode: 'mixWithOthers' }).catch(() => undefined);
      }
      p = audio.createAudioPlayer(SOURCES[name]) as Player;
      players.set(name, p);
    } catch {
      return null;
    }
  }
  return p;
}

/** Creates the players up front so the first effect plays without a loading delay. */
export function preloadSounds(): void {
  for (const name of Object.keys(SOURCES) as SoundName[]) player(name);
}

export function playSound(name: SoundName): void {
  if (soundMuted.get()) return;
  const p = player(name);
  if (!p) return;
  try {
    // Restart from the top: a finished player stays at its end otherwise.
    void p.seekTo(0).catch(() => undefined);
    p.play();
  } catch {
    // Sound is decoration; never let it break a screen.
  }
}
